import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    cap = int(data[pos]); pos += 1
    m = int(data[pos]); pos += 1

    buf = [0] * cap      # allocate once; never append, never pop(0)
    head = 0
    count = 0

    for _ in range(m):
        cmd = data[pos]; pos += 1
        if cmd == "push":
            x = int(data[pos]); pos += 1
            # full? otherwise buf[(head + count) % cap] = x
        elif cmd == "pop":
            pass
        elif cmd == "front":
            pass
        elif cmd == "back":
            pass
        elif cmd == "state":
            print("state head %d size %d" % (head, count))

main()
